package main

import "fmt"

func main() {
	// array: tamanho fixo (3), faz parte do tipo
	var arr [3]int = [3]int{1, 2, 3}

	// slice: tamanho flexível
	numeros := []int{10, 20, 30}
	numeros = append(numeros, 40) // cresce automaticamente

	fmt.Println(arr)      // [1 2 3]
	fmt.Println(numeros)  // [10 20 30 40]
	fmt.Println(len(numeros), cap(numeros))
}

