package main

import (
	"fmt"
	"os"
)

func lerArquivo(caminho string) error {
	arquivo, err := os.Open(caminho)
	if err != nil {
		return err
	}
	defer arquivo.Close() // sempre executado ao sair da função

	fmt.Println("arquivo aberto:", arquivo.Name())
	return nil
}

