}

package main

import "fmt"

func trabalhador(resultado chan<- int) {
	resultado <- 42 // envia o valor pelo canal
}

func main() {
	canal := make(chan int) // channel sem buffer

	go trabalhador(canal) // roda em outra goroutine

	valor := <-canal // espera receber o valor
	fmt.Println("recebido:", valor)
}

package main

import (
	"fmt"
	"time"
)

func main() {
	canal := make(chan string)

	go func() {
		time.Sleep(2 * time.Second)
		canal <- "resposta"
	}()

	select {
	case msg := <-canal:
		fmt.Println("recebido:", msg)
	case <-time.After(1 * time.Second):
		fmt.Println("tempo esgotado, desistindo")
	}
}

package main

import "fmt"

func criarContador() func() int {
	contagem := 0
	return func() int {
		contagem++ // a closure "lembra" da variável contagem
		return contagem
	}
}

func main() {
	proximo := criarContador()
	fmt.Println(proximo()) // 1
	fmt.Println(proximo()) // 2
	fmt.Println(proximo()) // 3
}

package main

import "fmt"

func soma(numeros ...int) int {
	total := 0
	for _, n := range numeros {
		total += n
	}
	return total
}

func main() {
	fmt.Println(soma(1, 2, 3))       // 6
	valores := []int{4, 5, 6}
	fmt.Println(soma(valores...))    // 15, espalhando o slice
}

