package main

import "fmt"

// T deve ser um tipo que suporta operadores de comparação
func Maior[T int | float64](a, b T) T {
	if a > b {
		return a
	}
	return b
}

func main() {
	fmt.Println(Maior(3, 7))         // funciona com int
	fmt.Println(Maior(2.5, 1.1))     // funciona com float64
}

package main

import "fmt"

func main() {
	dia := 3

	switch dia {
	case 1, 7:
		fmt.Println("fim de semana")
	case 2, 3, 4, 5, 6:
		fmt.Println("dia de semana")
	default:
		fmt.Println("dia inválido")
	}

	// switch sem expressão, como vários if
	idade := 20
	switch {
	case idade < 18:
		fmt.Println("menor de idade")
	case idade >= 18:
		fmt.Println("maior de idade")
	}
}

package main

import (
	"encoding/json"
	"fmt"
)

type Usuario struct {
	Nome  string `json:"nome"`
	Idade int    `json:"idade,omitempty"`
	Senha string `json:"-"` // nunca aparece no JSON
}

func main() {
	u := Usuario{Nome: "Ana", Idade: 30, Senha: "segredo"}

	dados, _ := json.Marshal(u)
	fmt.Println(string(dados)) // {"nome":"Ana","idade":30}

	var outro Usuario
	json.Unmarshal(dados, &outro)
	fmt.Println(outro.Nome) // Ana
}

package main

import "testing"

func Dobro(n int) int { return n * 2 }

func TestDobro(t *testing.T) {
	casos := []struct {
		nome     string
		entrada  int
		esperado int
	}{
		{"positivo", 3, 6},
		{"zero", 0, 0},
		{"negativo", -2, -4},
	}

	for _, c := range casos {
		t.Run(c.nome, func(t *testing.T) {
			resultado := Dobro(c.entrada)
			if resultado != c.esperado {
				t.Errorf("Dobro(%d) = %d; esperado %d", c.entrada, resultado, c.esperado)
			}
		})
	}
}

