package main

import "fmt"

func descrever(valor any) {
	switch v := valor.(type) {
	case int:
		fmt.Println("é um inteiro:", v)
	case string:
		fmt.Println("é uma string:", v)
	default:
		fmt.Println("tipo desconhecido")
	}
}

func main() {
	descrever(42)
	descrever("olá")
	descrever(3.14)
}
